import React, { useCallback, useMemo, useState } from 'react';
import {
  Button,
  Input,
  dispatchAppToast,
  getActiveCompanyCode,
  getAuthUser,
  LinPageLayout,
  useCatalogTableBusy,
  type LinListToolbarActionDef,
} from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch } from '../../../store/hooks';
import { analyticsService } from '../../../services/analytics/analyticsService';
import type {
  PrepaidAccruedExpenseListingColumn,
  PrepaidAccruedExpenseListingDetailRow,
  PrepaidAccruedExpenseListingRow,
} from '../../../services/analytics/models';
import { formatDate, formatVnd } from '../../../utils/formatters';
import { exportExcel, monthStartEnd } from '../../../utils/exportExcel';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import erp from '../../../styles/erpPage.module.css';
import reportStyles from '../../../styles/erpReportPage.module.css';
import styles from './BangKeSo6TapHopChiPhiTraTruocPhaiTraPage.module.css';

const TEST_ID = 'rpt-nkbk-chi-phi-tra-truoc-phai-tra';
const PAGE_ID = 'baocao-bang-ke-so-6-tap-hop-chi-phi-tra-truoc-phai-tra';
const TITLE = 'Bảng kê số 6 - Tập hợp chi phí trả trước và chi phí phải trả';
const ACCOUNT_LOCK = '142';

type RowTag = 'GrandTotal' | 'Detail';
type DrillRowTag = 'Total' | 'Detail';

const PLACEHOLDER_COLUMNS: PrepaidAccruedExpenseListingColumn[] = [
  { key: 'entryDate', kind: 'fixed', headerVi: 'Ngày', headerEn: 'Date' },
  { key: 'debitSideTotal', kind: 'sideTotalDebit', headerVi: 'Tổng Nợ', headerEn: 'Debit total' },
  { key: 'creditSideTotal', kind: 'sideTotalCredit', headerVi: 'Tổng Có', headerEn: 'Credit total' },
];

const DRILL_HEADERS: { key: string; label: string; right?: boolean }[] = [
  { key: 'voucherDate', label: 'Ngày C.từ' },
  { key: 'documentType', label: 'Mã C.từ' },
  { key: 'voucherCode', label: 'Số Ct' },
  { key: 'customerCode', label: 'Mã khách' },
  { key: 'description', label: 'Diễn giải' },
  { key: 'accountCode', label: 'Tài khoản' },
  { key: 'counterpartAccountCode', label: 'TK đối ứng' },
  { key: 'debitAmount', label: 'Ps nợ', right: true },
  { key: 'creditAmount', label: 'Ps có', right: true },
  { key: 'maVv', label: 'Vụ việc' },
  { key: 'maPhi', label: 'Phí' },
  { key: 'maSp', label: 'Sản phẩm' },
  { key: 'maHd', label: 'Hợp đồng' },
  { key: 'parentVoucherCode', label: 'Mã Ct0' },
];

function sessionCompany(): string {
  return (getActiveCompanyCode() ?? getAuthUser()?.companyCode ?? '').trim();
}

function mapRowTag(raw: PrepaidAccruedExpenseListingRow['rowTag'], isBold?: boolean): RowTag {
  if (raw === 'GrandTotal') return 'GrandTotal';
  if (raw === 'Detail') return 'Detail';
  if (isBold) return 'GrandTotal';
  return 'Detail';
}

function normalizeItems(items: PrepaidAccruedExpenseListingRow[]): PrepaidAccruedExpenseListingRow[] {
  return items.map(r => {
    const rowTag = mapRowTag(r.rowTag, r.isBold);
    return {
      ...r,
      rowTag,
      isBold: rowTag === 'GrandTotal' || Boolean(r.isBold),
      detailOk: Boolean(r.detailOk ?? true),
      entryDate: r.entryDate ?? null,
      label: r.label ?? null,
      debitBuckets: r.debitBuckets ?? {},
      creditBuckets: r.creditBuckets ?? {},
      creditSideTotal: Number(r.creditSideTotal ?? 0),
      debitSideTotal: Number(r.debitSideTotal ?? 0),
    };
  });
}

function debitCodeOf(col: PrepaidAccruedExpenseListingColumn): string {
  if (col.debitAccountCode) return col.debitAccountCode;
  if (col.key?.startsWith('N')) return col.key.slice(1).replace(/_/g, '.');
  return '';
}

function creditCodeOf(col: PrepaidAccruedExpenseListingColumn): string {
  if (col.creditAccountCode) return col.creditAccountCode;
  if (col.key?.startsWith('C')) return col.key.slice(1).replace(/_/g, '.');
  return '';
}

function isMoneyCol(col: PrepaidAccruedExpenseListingColumn): boolean {
  return (
    col.kind === 'debit'
    || col.kind === 'credit'
    || col.kind === 'sideTotalDebit'
    || col.kind === 'sideTotalCredit'
    || col.key === 'creditSideTotal'
    || col.key === 'debitSideTotal'
  );
}

function isSideTotalDebitCol(col: PrepaidAccruedExpenseListingColumn): boolean {
  return col.kind === 'sideTotalDebit' || col.key === 'debitSideTotal';
}

function isSideTotalCreditCol(col: PrepaidAccruedExpenseListingColumn): boolean {
  return col.kind === 'sideTotalCredit' || col.key === 'creditSideTotal';
}

function mapDrillTag(raw: PrepaidAccruedExpenseListingDetailRow['rowTag']): DrillRowTag {
  if (raw === 'Total') return 'Total';
  return 'Detail';
}

function drillRowClass(tag: DrillRowTag): string {
  if (tag === 'Total') return styles.rowToneDrillTotal;
  return styles.rowToneDrillDetail;
}

type DrillParams = {
  fromDate: string;
  toDate: string;
};

const BangKeSo6TapHopChiPhiTraTruocPhaiTraPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const initial = monthStartEnd();

  const [fromDate, setFromDate] = useState(initial.fromDate);
  const [toDate, setToDate] = useState(initial.toDate);
  const [aggregateByParentCreditAccount, setAggregateByParentCreditAccount] = useState(false);
  const [columns, setColumns] = useState<PrepaidAccruedExpenseListingColumn[]>(PLACEHOLDER_COLUMNS);
  const [items, setItems] = useState<PrepaidAccruedExpenseListingRow[]>([]);
  const [metaDebitSideGrand, setMetaDebitSideGrand] = useState<number | null>(null);
  const [metaCreditSideGrand, setMetaCreditSideGrand] = useState<number | null>(null);
  const [appliedFrom, setAppliedFrom] = useState('');
  const [appliedTo, setAppliedTo] = useState('');
  const [appliedAggregate, setAppliedAggregate] = useState(false);
  const [hasViewed, setHasViewed] = useState(false);
  const [loading, setLoading] = useState(false);
  const [filterError, setFilterError] = useState('');
  const [drillOpen, setDrillOpen] = useState(false);
  const [drillParams, setDrillParams] = useState<DrillParams | null>(null);
  const [drillItems, setDrillItems] = useState<PrepaidAccruedExpenseListingDetailRow[]>([]);
  const [drillLoading, setDrillLoading] = useState(false);
  const { showTableLoading } = useCatalogTableBusy(loading);

  const displayColumns = hasViewed && columns.length > 0 ? columns : PLACEHOLDER_COLUMNS;

  const summarySides = useMemo(() => {
    if (!hasViewed) return null;
    const gt = items.find(r => mapRowTag(r.rowTag, r.isBold) === 'GrandTotal');
    const debit =
      metaDebitSideGrand != null
        ? metaDebitSideGrand
        : gt
          ? Number(gt.debitSideTotal ?? 0)
          : null;
    const credit =
      metaCreditSideGrand != null
        ? metaCreditSideGrand
        : gt
          ? Number(gt.creditSideTotal ?? 0)
          : null;
    if (debit == null && credit == null) return null;
    return { debit, credit };
  }, [hasViewed, items, metaCreditSideGrand, metaDebitSideGrand]);

  const detailCount = useMemo(
    () => items.filter(r => mapRowTag(r.rowTag, r.isBold) === 'Detail').length,
    [items],
  );

  const handleView = useCallback(() => {
    setFilterError('');
    const company = sessionCompany();
    if (!company) {
      setFilterError('Không xác định đơn vị');
      dispatchAppToast(dispatch, { message: 'Không xác định đơn vị', type: 'error' });
      return;
    }
    if (!fromDate.trim() || !toDate.trim()) {
      setFilterError('Chọn khoảng ngày');
      dispatchAppToast(dispatch, { message: 'Chọn khoảng ngày', type: 'error' });
      return;
    }
    if (toDate < fromDate) {
      setFilterError('Đến ngày phải ≥ Từ ngày');
      dispatchAppToast(dispatch, { message: 'Đến ngày phải ≥ Từ ngày', type: 'error' });
      return;
    }

    setLoading(true);
    analyticsService
      .getPrepaidAccruedExpenseListing({
        fromDate: fromDate.trim(),
        toDate: toDate.trim(),
        accountCode: ACCOUNT_LOCK,
        aggregateByParentCreditAccount,
        pageSize: 0,
      })
      .then(report => {
        const nextCols =
          Array.isArray(report.columns) && report.columns.length > 0
            ? report.columns
            : PLACEHOLDER_COLUMNS;
        setColumns(nextCols);
        setItems(normalizeItems(report.items ?? []));
        setMetaDebitSideGrand(
          report.meta?.debitSideTotal != null
            ? Number(report.meta.debitSideTotal)
            : report.summary?.debitSideTotal != null
              ? Number(report.summary.debitSideTotal)
              : null,
        );
        setMetaCreditSideGrand(
          report.meta?.creditSideTotal != null
            ? Number(report.meta.creditSideTotal)
            : report.summary?.creditSideTotal != null
              ? Number(report.summary.creditSideTotal)
              : null,
        );
        setAppliedFrom(fromDate.trim());
        setAppliedTo(toDate.trim());
        setAppliedAggregate(aggregateByParentCreditAccount);
        setHasViewed(true);
      })
      .catch(err => {
        dispatchAppToast(dispatch, {
          message: getApiErrorMessage(
            err,
            'Không tải được bảng kê số 6 - tập hợp chi phí trả trước và phải trả',
          ),
          type: 'error',
        });
      })
      .finally(() => setLoading(false));
  }, [aggregateByParentCreditAccount, dispatch, fromDate, toDate]);

  const onEnterView = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleView();
      }
    },
    [handleView],
  );

  const handleRefresh = useCallback(() => {
    const next = monthStartEnd();
    setFromDate(next.fromDate);
    setToDate(next.toDate);
    setAggregateByParentCreditAccount(false);
    setFilterError('');
  }, []);

  const handleExport = useCallback(() => {
    if (!hasViewed || loading || !appliedFrom || !appliedTo) return;
    const fileName = `bang-ke-so-6-tap-hop-chi-phi-tra-truoc-phai-tra_${appliedFrom}_${appliedTo}.xlsx`;
    void exportExcel(
      '/accounting/prepaid-accrued-expense-listing/export-excel',
      {
        fromDate: appliedFrom,
        toDate: appliedTo,
        accountCode: ACCOUNT_LOCK,
        aggregateByParentCreditAccount: appliedAggregate,
        pageSize: 0,
      },
      fileName,
    ).catch(() => {
      /* toast already in exportExcel */
    });
  }, [appliedAggregate, appliedFrom, appliedTo, hasViewed, loading]);

  const handlePrint = useCallback(() => {
    window.print();
  }, []);

  const openDrill = useCallback((params: DrillParams) => {
    setDrillParams(params);
    setDrillOpen(true);
    setDrillLoading(true);
    setDrillItems([]);
    analyticsService
      .getPrepaidAccruedExpenseListingDetail({
        fromDate: params.fromDate,
        toDate: params.toDate,
        accountCode: ACCOUNT_LOCK,
        pageSize: 0,
      })
      .then(report => {
        setDrillItems(report.items ?? []);
      })
      .catch(err => {
        dispatchAppToast(dispatch, {
          message: getApiErrorMessage(err, 'Không tải được chi tiết bảng kê CP trả trước/phải trả'),
          type: 'error',
        });
      })
      .finally(() => setDrillLoading(false));
  }, [dispatch]);

  const closeDrill = useCallback(() => {
    setDrillOpen(false);
    setDrillParams(null);
    setDrillItems([]);
  }, []);

  const onCellDrill = useCallback(
    (row: PrepaidAccruedExpenseListingRow) => {
      if (!hasViewed || !appliedFrom || !appliedTo) return;
      const tag = mapRowTag(row.rowTag, row.isBold);
      if (tag === 'GrandTotal') {
        openDrill({ fromDate: appliedFrom, toDate: appliedTo });
        return;
      }
      if (!row.detailOk) return;
      const day = (row.entryDate ?? '').trim();
      if (!day) return;
      openDrill({ fromDate: day, toDate: day });
    },
    [appliedFrom, appliedTo, hasViewed, openDrill],
  );

  const exportDisabled = !hasViewed || loading || !appliedFrom;

  const toolbarActions = useMemo<LinListToolbarActionDef[]>(
    () => [
      {
        id: 'refresh',
        action: 'refresh',
        placement: 'left',
        label: 'Làm mới',
        variant: 'secondary',
        testId: `${TEST_ID}-toolbar-refresh-btn`,
        disabled: loading,
        onClick: handleRefresh,
      },
      {
        id: 'export-excel',
        action: 'exportExcel',
        placement: 'left',
        label: 'Xuất Excel',
        variant: 'secondary',
        testId: `${TEST_ID}-export-excel`,
        disabled: exportDisabled,
        onClick: handleExport,
      },
      {
        id: 'print',
        action: 'print',
        placement: 'left',
        label: 'In',
        variant: 'secondary',
        testId: `${TEST_ID}-export-print`,
        disabled: !hasViewed || loading,
        onClick: handlePrint,
      },
    ],
    [exportDisabled, handleExport, handlePrint, handleRefresh, hasViewed, loading],
  );

  const subtitle =
    hasViewed && appliedFrom && appliedTo
      ? `Từ: ${formatDate(appliedFrom)} đến ngày ${formatDate(appliedTo)} · TK: ${ACCOUNT_LOCK}`
      : undefined;

  const drillTitle = 'Chi tiết bảng kê số 6 - CP trả trước và phải trả';

  const listBody = showTableLoading ? null : (
    <div className={erp.tableWrapper}>
      {subtitle ? (
        <div
          data-testid={`${TEST_ID}-subtitle`}
          className={reportStyles.subtitle}
          style={{ marginBottom: '0.5rem' }}
        >
          {subtitle}
        </div>
      ) : null}
      {!hasViewed ? (
        <div className={erp.empty} style={{ marginBottom: '0.5rem' }}>
          Chọn khoảng ngày và bấm Xem
        </div>
      ) : null}
      <div className={styles.gridScroll} data-testid={`${TEST_ID}-grid-scroll`}>
        <table className={reportStyles.table} data-testid={`${TEST_ID}-grid`}>
          <thead>
            <tr>
              {displayColumns.map(col => {
                const money = isMoneyCol(col);
                const code =
                  col.kind === 'credit'
                    ? creditCodeOf(col)
                    : col.kind === 'debit'
                      ? debitCodeOf(col)
                      : '';
                return (
                  <th
                    key={col.key}
                    className={money ? reportStyles.colRight : undefined}
                    data-testid={
                      col.kind === 'debit' && code
                        ? `${TEST_ID}-col-debit-${code}`
                        : col.kind === 'credit' && code
                          ? `${TEST_ID}-col-credit-${code}`
                          : undefined
                    }
                  >
                    {col.headerVi ?? col.key}
                  </th>
                );
              })}
            </tr>
          </thead>
          <tbody>
            {!hasViewed
              ? null
              : items.map((row, index) => {
                  const tag = mapRowTag(row.rowTag, row.isBold);
                  const isGrand = tag === 'GrandTotal';
                  const canDrill =
                    isGrand || (tag === 'Detail' && Boolean(row.detailOk));
                  return (
                    <tr
                      key={`${tag}|${row.entryDate ?? 'GT'}|${index}`}
                      className={isGrand ? styles.rowToneGrandTotal : styles.rowToneDetail}
                      data-testid={`${TEST_ID}-row-${index}`}
                      data-row-tag={tag}
                      data-entry-date={row.entryDate ?? ''}
                      data-is-bold={isGrand || row.isBold ? '1' : '0'}
                      data-detail-ok={canDrill ? '1' : '0'}
                    >
                      {displayColumns.map(col => {
                        if (col.key === 'entryDate' || col.kind === 'fixed') {
                          return (
                            <td key={col.key}>
                              {isGrand
                                ? (row.label?.trim() || 'Tổng cộng')
                                : row.entryDate
                                  ? formatDate(row.entryDate)
                                  : ''}
                            </td>
                          );
                        }

                        if (col.kind === 'credit') {
                          const code = creditCodeOf(col);
                          const amount = Number(row.creditBuckets?.[code] ?? 0);
                          return (
                            <td
                              key={col.key}
                              className={`${styles.cellMoney}${
                                canDrill ? ` ${styles.cellDrillable}` : ''
                              }`}
                              data-testid={`${TEST_ID}-cell-${index}-${col.key}`}
                              data-drillable={canDrill ? '1' : '0'}
                              title={canDrill ? 'Xem chi tiết chứng từ' : undefined}
                              onClick={canDrill ? () => onCellDrill(row) : undefined}
                            >
                              {formatVnd(amount)}
                            </td>
                          );
                        }

                        if (isSideTotalDebitCol(col)) {
                          return (
                            <td
                              key={col.key}
                              className={`${styles.cellSideTotal} ${styles.cellMoney}${
                                canDrill ? ` ${styles.cellDrillable}` : ''
                              }`}
                              data-drillable={canDrill ? '1' : '0'}
                              title={canDrill ? 'Xem chi tiết chứng từ' : undefined}
                              onClick={canDrill ? () => onCellDrill(row) : undefined}
                            >
                              {formatVnd(Number(row.debitSideTotal ?? 0))}
                            </td>
                          );
                        }

                        if (col.kind === 'debit') {
                          const code = debitCodeOf(col);
                          const amount = Number(row.debitBuckets?.[code] ?? 0);
                          return (
                            <td
                              key={col.key}
                              className={`${styles.cellMoney}${
                                canDrill ? ` ${styles.cellDrillable}` : ''
                              }`}
                              data-testid={`${TEST_ID}-cell-${index}-${col.key}`}
                              data-drillable={canDrill ? '1' : '0'}
                              title={canDrill ? 'Xem chi tiết chứng từ' : undefined}
                              onClick={canDrill ? () => onCellDrill(row) : undefined}
                            >
                              {formatVnd(amount)}
                            </td>
                          );
                        }

                        if (isSideTotalCreditCol(col)) {
                          return (
                            <td
                              key={col.key}
                              className={`${styles.cellSideTotal} ${styles.cellMoney}${
                                canDrill ? ` ${styles.cellDrillable}` : ''
                              }`}
                              data-drillable={canDrill ? '1' : '0'}
                              title={canDrill ? 'Xem chi tiết chứng từ' : undefined}
                              onClick={canDrill ? () => onCellDrill(row) : undefined}
                            >
                              {formatVnd(Number(row.creditSideTotal ?? 0))}
                            </td>
                          );
                        }

                        return <td key={col.key} />;
                      })}
                    </tr>
                  );
                })}
          </tbody>
        </table>
      </div>
      {hasViewed && detailCount === 0 ? (
        <div className={erp.empty} data-testid={`${TEST_ID}-empty`}>
          Không có dữ liệu
        </div>
      ) : null}
    </div>
  );

  const footer =
    hasViewed && summarySides ? (
      <div className={styles.summaryBar} data-testid={`${TEST_ID}-summary`}>
        {summarySides.debit != null ? (
          <span>Tổng Nợ: {formatVnd(summarySides.debit)}</span>
        ) : null}
        {summarySides.credit != null ? (
          <span>Tổng Có: {formatVnd(summarySides.credit)}</span>
        ) : null}
      </div>
    ) : undefined;

  return (
    <div
      className={erp.voucherListRoot}
      data-catalog-list-page
      data-report-list-page
      data-testid={`${TEST_ID}-list`}
    >
      <LinPageLayout
        kind="report"
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        pageClassName={`${erp.catalogListPage} ${erp.voucherListPage}`}
        header={{ title: TITLE, titleIconClass: 'fas fa-list' }}
        listTitle={TITLE}
        filterMaxWidthPx={1400}
        showTableLoading={showTableLoading}
        skeletonRows={8}
        toolbarProps={{
          testIdPrefix: TEST_ID,
          profile: 'report',
          actions: toolbarActions,
        }}
        footer={footer}
        filters={(
          <>
            <div data-testid={`${TEST_ID}-field-fromDate`}>
              <Input
                type="date"
                label="Từ ngày"
                value={fromDate}
                onChange={e => setFromDate(e.target.value)}
                onKeyDown={onEnterView}
                data-testid={`${TEST_ID}-field-from`}
              />
            </div>
            <div data-testid={`${TEST_ID}-field-toDate`}>
              <Input
                type="date"
                label="Đến ngày"
                value={toDate}
                onChange={e => setToDate(e.target.value)}
                onKeyDown={onEnterView}
                data-testid={`${TEST_ID}-field-to`}
              />
            </div>
            <div
              className={styles.accountLockBadge}
              data-testid={`${TEST_ID}-field-accountCode`}
            >
              TK: <strong>{ACCOUNT_LOCK}</strong>
            </div>
            <div
              className={styles.aggregateCheck}
              data-testid={`${TEST_ID}-field-aggregateByParentCreditAccount`}
            >
              <input
                id={`${TEST_ID}-aggregate`}
                type="checkbox"
                checked={aggregateByParentCreditAccount}
                onChange={e => setAggregateByParentCreditAccount(e.target.checked)}
                data-testid={`${TEST_ID}-field-aggregate`}
              />
              <label htmlFor={`${TEST_ID}-aggregate`}>Theo TK tổng hợp</label>
            </div>
            <Button
              variant="primary"
              onClick={handleView}
              disabled={loading}
              data-testid={`${TEST_ID}-view-btn`}
            >
              Xem
            </Button>
            {filterError ? (
              <div className={styles.filterError} data-testid={`${TEST_ID}-filter-error`}>
                {filterError}
              </div>
            ) : null}
          </>
        )}
        modals={
          drillOpen ? (
            <div
              className={styles.drillOverlay}
              data-testid={`${TEST_ID}-drill-modal`}
              role="dialog"
              aria-modal="true"
              onClick={e => {
                if (e.target === e.currentTarget) closeDrill();
              }}
            >
              <div className={styles.drillModal}>
                <div className={styles.drillHeader}>
                  <h3 className={styles.drillTitle}>{drillTitle}</h3>
                  <Button
                    variant="secondary"
                    onClick={closeDrill}
                    data-testid={`${TEST_ID}-drill-close`}
                  >
                    Đóng
                  </Button>
                </div>
                {drillLoading ? (
                  <div>Đang tải...</div>
                ) : (
                  <>
                    <div className={styles.gridScroll}>
                      <table
                        className={reportStyles.table}
                        data-testid={`${TEST_ID}-drill-grid`}
                      >
                        <thead>
                          <tr>
                            {DRILL_HEADERS.map(h => (
                              <th
                                key={h.key}
                                className={h.right ? reportStyles.colRight : undefined}
                              >
                                {h.label}
                              </th>
                            ))}
                          </tr>
                        </thead>
                        <tbody>
                          {drillItems.map((row, index) => {
                            const tag = mapDrillTag(row.rowTag);
                            const isTotal = tag === 'Total';
                            return (
                              <tr
                                key={`${tag}|${row.voucherCode ?? ''}|${index}`}
                                className={drillRowClass(tag)}
                                data-row-tag={tag}
                              >
                                <td>
                                  {!isTotal && row.voucherDate
                                    ? formatDate(row.voucherDate)
                                    : ''}
                                </td>
                                <td>{isTotal ? '' : (row.documentType ?? '')}</td>
                                <td>{isTotal ? '' : (row.voucherCode ?? '')}</td>
                                <td>{isTotal ? '' : (row.customerCode ?? '')}</td>
                                <td>{row.description ?? ''}</td>
                                <td>{isTotal ? '' : (row.accountCode ?? '')}</td>
                                <td>{isTotal ? '' : (row.counterpartAccountCode ?? '')}</td>
                                <td className={reportStyles.colRight}>
                                  {row.debitAmount == null
                                    ? ''
                                    : formatVnd(Number(row.debitAmount))}
                                </td>
                                <td className={reportStyles.colRight}>
                                  {row.creditAmount == null
                                    ? ''
                                    : formatVnd(Number(row.creditAmount))}
                                </td>
                                <td>{isTotal ? '' : (row.maVv ?? '')}</td>
                                <td>{isTotal ? '' : (row.maPhi ?? '')}</td>
                                <td>{isTotal ? '' : (row.maSp ?? '')}</td>
                                <td>{isTotal ? '' : (row.maHd ?? '')}</td>
                                <td>{isTotal ? '' : (row.parentVoucherCode ?? '')}</td>
                              </tr>
                            );
                          })}
                        </tbody>
                      </table>
                    </div>
                    {!drillLoading &&
                    drillItems.filter(r => mapDrillTag(r.rowTag) === 'Detail').length === 0 ? (
                      <div
                        className={styles.drillEmpty}
                        data-testid={`${TEST_ID}-drill-empty`}
                      >
                        Không có dữ liệu chi tiết
                      </div>
                    ) : null}
                  </>
                )}
              </div>
            </div>
          ) : undefined
        }
      >
        {listBody}
      </LinPageLayout>
    </div>
  );
};

export default BangKeSo6TapHopChiPhiTraTruocPhaiTraPage;
